create extension if not exists pgcrypto;
create table if not exists customers(id uuid primary key default gen_random_uuid(),name text not null,phone text not null unique,created_at timestamptz not null default now());
create table if not exists drivers(id uuid primary key default gen_random_uuid(),name text not null,phone text not null unique,vehicle text not null,availability text not null default 'offline',rating numeric(3,2) default 5,trips integer not null default 0,latitude numeric(10,7),longitude numeric(10,7),last_location_at timestamptz,created_at timestamptz not null default now());
create table if not exists bookings(id uuid primary key default gen_random_uuid(),reference text not null unique,customer_id uuid references customers(id),driver_id uuid references drivers(id),customer_name text not null,customer_phone text not null,booking_date date not null,booking_time time not null,pickup text not null,destination text not null,vehicle text not null,distance_km numeric(10,2),fare integer not null,payment_method text not null,payment_status text not null default 'pending',status text not null default 'confirmed',razorpay_order_id text,razorpay_payment_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists booking_status_history(id bigserial primary key,booking_id uuid not null references bookings(id) on delete cascade,status text not null,actor_type text,actor_id text,notes text,created_at timestamptz not null default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),booking_id uuid references bookings(id),provider text not null,provider_order_id text,provider_payment_id text,amount integer not null,currency text not null default 'INR',status text not null,raw_event jsonb,created_at timestamptz not null default now());
create table if not exists webhook_events(id bigserial primary key,provider text not null,event_id text,signature text,received_at timestamptz not null default now(),payload jsonb not null,unique(provider,event_id));
create index if not exists idx_bookings_status on bookings(status);
create index if not exists idx_bookings_driver on bookings(driver_id);
create index if not exists idx_drivers_availability on drivers(availability);
create index if not exists idx_driver_location on drivers(latitude,longitude);
